/**
 * Mock for the native `ExpoNavigationBar` module, which is used by the expo jest preset.
 *
 * The native module exists only on Android, so this file is written by hand instead of
 * being generated by expo-modules-test-core from the iOS implementation.
 */

export type NavigationBarVisibility = 'visible' | 'hidden';

export async function setStyle(style: string): Promise<void> {}

export async function setHidden(hidden: boolean): Promise<void> {}

export async function getVisibilityAsync(): Promise<NavigationBarVisibility> {
  return 'visible';
}
